H.background();
const w = H.W;
const c = 2.998e8;            // speed of light, m/s
const m = Math.max(0.001, P.m);   // mass in kilograms
const E0 = m * c * c;        // rest energy, joules
// Total relativistic energy as the object's speed oscillates 0..betaMax.
const betaMax = Math.min(0.99, Math.max(0, P.betaMax));
const beta = betaMax * 0.5 * (1 - Math.cos(t * 0.8)); // 0..betaMax, looping
const gamma = 1 / Math.sqrt(Math.max(1e-6, 1 - beta * beta));
const E = gamma * E0;        // total energy = gamma m c^2
const v = H.plot2d({ xMin: 0, xMax: 1, yMin: 0, yMax: 8 });
v.grid({ stepX: 0.2 }); v.axes();
// Energy as a multiple of rest energy (E/E0 = gamma) versus beta.
v.fn(b => 1 / Math.sqrt(Math.max(1e-4, 1 - b * b)), { color: H.colors.accent, width: 3 });
v.line(0, 1, 1, 1, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.dot(beta, Math.min(8, gamma), { r: 7, fill: H.colors.warn });
v.text("E0 = m c²", 0.04, 1.5, { color: H.colors.violet, size: 12 });
H.text("Mass–energy: E = γ·m·c²  (rest: E0 = m·c²)", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("m = " + m.toFixed(3) + " kg    c = 2.998e8 m/s    β = " + beta.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
H.text("E0 = " + E0.toExponential(3) + " J     E = γ E0 = " + E.toExponential(3) + " J", 24, 74, { color: H.colors.good, size: 13 });
